<template><section aria-label="完整排班场景原声明">
 <p>逐项声明实际场景；留空的资格、覆盖、工时、惩罚或容量不会补成已核实、无限制或零。所有本科室人员均保留，包括没有旧排班的人。</p>
 <el-form label-position="top" :disabled="disabled" @submit.prevent><el-form-item v-for="[key,label] in [['date_from','规划首业务日期'],['date_to','规划末业务日期'],['business_timezone','实际IANA业务时区']]" :key="key" :label="label"><el-input v-model="draft[key]" :aria-label="label" :placeholder="key==='business_timezone'?'例如 Asia/Shanghai，须明确填写':'YYYY-MM-DD，不超过连续31日'" /></el-form-item><el-form-item label="排班固定优化目标"><el-select v-model="draft.objective_mode" aria-label="排班固定优化目标" placeholder="请明确选择"><el-option label="满足硬需求后最小化明确惩罚" value="meet_targets_min_penalty" /><el-option label="先最大化计划净服务量，再最小化惩罚" value="max_slots_then_min_penalty" /></el-select></el-form-item>
 <template v-for="[key,label] in [['personnel_coverage','本科人员集合覆盖'],['session_requirements_coverage','会话需求集合覆盖']]" :key="key"><el-form-item :label="label"><el-select v-model="draft[key].status" :aria-label="label" placeholder="明确核实状态"><el-option v-for="[value,text] in coverage" :key="value" :value="value" :label="text" /></el-select></el-form-item><el-form-item :label="label+'依据'"><el-input v-model="draft[key].basis" :aria-label="label+'依据'" type="textarea" maxlength="4000" placeholder="至少20个非空白字符，仅院内核对" /></el-form-item></template>
 <el-form-item label="人工候选提交方式"><el-select v-model="candidateMode" aria-label="人工候选提交方式" placeholder="明确是否有人工候选"><el-option label="不提交人工候选，保留为null" value="none" /><el-option label="明确提交下方勾选的人工候选（可为空）" value="provided" /></el-select></el-form-item>
 <p>人数 {{ staff.length }}；会话 {{ sessions.length }}；完整人员与会话配对 {{ options.length }}。分页只限制页面，不省略请求成员。上限512人、256会话及32768配对，超过范围明确阻止。</p>
 <el-radio-group v-model="group" aria-label="场景声明分组"><el-radio-button value="staff">所有人员覆盖</el-radio-button><el-radio-button value="sessions">明确日期会话</el-radio-button><el-radio-button value="options">完整人员与会话配对</el-radio-button></el-radio-group><el-button v-if="group==='sessions'" :disabled="sessions.length>=256||staff.length*(sessions.length+1)>32768" @click="addSession">添加明确日期会话</el-button>
 <el-table :data="visible" :row-key="rowKey" aria-label="完整排班场景分页声明"><el-table-column label="原成员" min-width="260"><template #default="{row}">{{ identity(row) }}</template></el-table-column><el-table-column label="明确状态" min-width="180"><template #default="{row}">{{ rowReady(row)?'所需原字段已填写':'仍有未填写或需核对字段' }}</template></el-table-column><el-table-column label="操作" width="220"><template #default="{row}"><el-button @click="editing=row">填写此{{ group==='staff'?'人员覆盖':group==='sessions'?'日期会话':'配对声明' }}</el-button><el-button v-if="group==='sessions'" @click="removeSession(row)">移除此未提交会话</el-button><el-checkbox v-if="group==='options'&&candidateMode==='provided'" v-model="row.selected" :aria-label="`人工候选${row.doctor_id}:${row.session_key}`">纳入人工候选</el-checkbox></template></el-table-column></el-table><el-pagination v-if="rows.length>20" v-model:current-page="page" :total="rows.length" :page-size="20" layout="prev,pager,next" />
 </el-form><p v-if="!valid" role="status">全部人员、会话和配对均须明确填写；未显示页也会逐项检查。不能仅提交本页。</p>
 <el-dialog v-model="editOpen" :title="`填写排班${group==='staff'?'人员覆盖':group==='sessions'?'日期会话':'人员会话配对'}原声明`" width="min(850px,95vw)"><el-form v-if="editing" label-position="top" :disabled="disabled" @submit.prevent><p>{{ identity(editing) }}</p>
 <template v-if="group==='staff'"><p>核实全部地点的实际值班记录范围，包含原院外工作和规划前后必要上下文；未知范围不等于没有工作。</p><el-form-item v-for="[key,label] in [['start_at','全部地点值班覆盖开始UTC'],['end_at','全部地点值班覆盖结束UTC']]" :key="key" :label="label"><el-input v-model="editing.coverage[key]" :aria-label="label" /></el-form-item><el-form-item label="全部地点值班覆盖状态"><el-select v-model="editing.coverage.status" aria-label="全部地点值班覆盖状态" placeholder="明确选择"><el-option v-for="[value,label] in coverage" :key="value" :value="value" :label="label" /></el-select></el-form-item></template>
 <template v-else-if="group==='sessions'"><el-form-item v-for="[key,label] in [['business_date','会话原业务日期'],['start_at','会话原开始UTC'],['end_at','会话原结束UTC'],['required_job_key','会话原要求岗位代码'],['minimum_staff','会话原最少人数'],['maximum_staff','会话原最多人数']]" :key="key" :label="label"><el-input v-model="editing[key]" :aria-label="label" /></el-form-item><nullable-value v-model="editing.required_slots" label="会话原硬需求服务量" unit="个场景服务量" /><nullable-value v-model="editing.facility_slot_ceiling" label="会话原场景设施净容量上限" unit="个场景服务量" /><p>场景净容量须有明确依据，不能填写共享库存余量、实时可预约余号或预测到诊人数。</p><el-form-item label="会话原容量依据"><el-input v-model="editing.capacity_basis" aria-label="会话原容量依据" type="textarea" maxlength="4000" /></el-form-item></template>
 <template v-else><nullable-value v-model="editing.cost_points" label="配对原惩罚点" unit="惩罚点" /><nullable-value v-model="editing.slot_capacity" label="配对原场景净服务量" unit="个场景服务量" /><el-form-item label="配对原休息记录完整状态"><el-select v-model="editing.breaks_complete" aria-label="配对原休息记录完整状态" placeholder="请明确选择"><el-option :value="true" label="明确全部休息已核全（true）" /><el-option :value="false" label="明确休息尚未核全（false）" /></el-select></el-form-item><el-form-item label="配对原时间核算状态"><el-select v-model="editing.time_accounting_status" aria-label="配对原时间核算状态" placeholder="请明确选择"><el-option value="verified" label="原核算已核实" /><el-option value="unknown" label="原核算未知" /></el-select></el-form-item><breaks-editor v-model="editing.breaks" :disabled="disabled" /></template>
 <el-form-item :label="editBasisLabel"><el-input v-model="basis" :aria-label="editBasisLabel" type="textarea" maxlength="4000" placeholder="至少20个非空白字符，明确此原成员与本次用途依据" /></el-form-item></el-form><template #footer><el-button @click="editing=null">保留填写并关闭</el-button></template></el-dialog>
</section></template>
<script setup>
import {computed,ref,watch} from 'vue';import NullableValue from '@/components/AIRosterSources/NullableValue.vue';import BreaksEditor from '@/components/AIRosterSources/BreaksEditor.vue';import {supportUtc} from '@/api/inpatientSupport';import {rosterBasisValid} from '@/api/rosterSources';import {rosterPlanRequestValid,rosterSchemaMatches} from '@/api/rosterPlans';
const props=defineProps({departmentId:{type:Number,required:true},doctors:{type:Array,required:true},disabled:{type:Boolean,default:false}}),emit=defineEmits(['change','validity']);
const coverage=[['attested_complete','明确已核完整'],['incomplete','明确资料不完整'],['unknown','原覆盖未知']],draft=ref({personnel_coverage:{},session_requirements_coverage:{}}),staff=ref(props.doctors.map(row=>({doctor_id:row.doctor_id,coverage:{}}))),sessions=ref([]),options=ref([]),candidateMode=ref(''),group=ref('staff'),editing=ref(null),page=ref(1),editOpen=computed({get:()=>!!editing.value,set:v=>{if(!v)editing.value=null;}});
const rows=computed(()=>group.value==='staff'?staff.value:group.value==='sessions'?sessions.value:options.value),visible=computed(()=>rows.value.slice((page.value-1)*20,page.value*20)),rowKey=row=>row.doctor_id&&row.session_key?`${row.doctor_id}:${row.session_key}`:row.session_key||row.doctor_id;
function identity(row){const person=props.doctors.find(item=>item.doctor_id===row.doctor_id),session=sessions.value.find(item=>item.session_key===row.session_key);return`${row.doctor_id?`${person?.name||'原人员'} #${row.doctor_id}`:''}${row.session_key?` · ${session?.business_date||'未填日期'} · ${row.session_key}`:''}`;}
const editBasisLabel=computed(()=>group.value==='staff'?'人员全部地点值班覆盖依据':group.value==='sessions'?'会话原硬需求依据':'人员会话配对原依据'),basis=computed({get:()=>group.value==='staff'?editing.value?.coverage.basis:group.value==='sessions'?editing.value?.requirements_basis:editing.value?.basis,set:v=>{if(!editing.value)return;if(group.value==='staff')editing.value.coverage.basis=v;else editing.value[group.value==='sessions'?'requirements_basis':'basis']=v;}});
const integer=value=>/^(?:0|[1-9]\d*)$/.test(String(value))?Number(value):undefined;
function quantity(row){if(['unknown','not_applicable'].includes(row?.state))return{value:null,absent_reason:row.state};if(row?.state!=='known')throw new Error('请明确选择原整数或缺项原因');return{value:integer(row.value),absent_reason:null};}
function buildRow(row,type=group.value){if(type==='staff')return{doctor_id:row.doctor_id,all_locations_duty_coverage:{start_at:supportUtc(row.coverage.start_at),end_at:supportUtc(row.coverage.end_at),status:row.coverage.status,basis:row.coverage.basis}};if(type==='sessions')return{session_key:row.session_key,business_date:row.business_date,start_at:supportUtc(row.start_at),end_at:supportUtc(row.end_at),required_job_key:row.required_job_key,minimum_staff:integer(row.minimum_staff),maximum_staff:integer(row.maximum_staff),required_slots:quantity(row.required_slots),facility_slot_ceiling:quantity(row.facility_slot_ceiling),requirements_basis:row.requirements_basis,capacity_basis:row.capacity_basis};return{doctor_id:row.doctor_id,session_key:row.session_key,cost_points:quantity(row.cost_points),slot_capacity:quantity(row.slot_capacity),breaks_complete:row.breaks_complete,time_accounting_status:row.time_accounting_status,basis:row.basis,breaks:row.breaks.map(item=>{const state=item.accounting?.state,absent=['unknown','not_applicable'].includes(state);if(!absent&&!['true','false'].includes(state))throw new Error('请明确休息原核算');return{start_at:supportUtc(item.start_at),end_at:supportUtc(item.end_at),counted_as_work:absent?null:state==='true',counted_as_work_absent_reason:absent?state:null};})};}
function build(){if(!['none','provided'].includes(candidateMode.value))throw new Error('请明确人工候选提交方式');return{department_id:props.departmentId,...draft.value,staff:staff.value.map(row=>buildRow(row,'staff')),sessions:sessions.value.map(row=>buildRow(row,'sessions')),options:options.value.map(row=>buildRow(row,'options')),submitted_candidate:candidateMode.value==='none'?null:options.value.filter(row=>row.selected).map(row=>({doctor_id:row.doctor_id,session_key:row.session_key}))};}
function rowReady(row){try{const value=buildRow(row);return rosterSchemaMatches('PlanRequest',value,group.value==='staff'?'StaffDeclaration':group.value==='sessions'?'SessionDeclaration':'OptionDeclaration')&&rosterBasisValid(group.value==='staff'?value.all_locations_duty_coverage.basis:group.value==='sessions'?value.requirements_basis:value.basis);}catch{return false;}}
function addSession(){if(sessions.value.length>=256||staff.value.length*(sessions.value.length+1)>32768)return;const session={session_key:crypto.randomUUID(),required_slots:{},facility_slot_ceiling:{}};sessions.value.push(session);for(const person of staff.value)options.value.push({doctor_id:person.doctor_id,session_key:session.session_key,cost_points:{},slot_capacity:{},breaks:[]});editing.value=session;}
function removeSession(row){sessions.value=sessions.value.filter(item=>item!==row);options.value=options.value.filter(item=>item.session_key!==row.session_key);editing.value=null;}
const valid=computed(()=>{try{return rosterPlanRequestValid(build());}catch{return false;}});watch(valid,v=>emit('validity',v),{immediate:true});watch([draft,staff,sessions,options,candidateMode],()=>emit('change'),{deep:true,flush:'sync'});watch(group,()=>{page.value=1;editing.value=null;});watch(()=>rows.value.length,n=>page.value=Math.min(page.value,Math.max(1,Math.ceil(n/20))));defineExpose({build});
</script>
